import sys
from collections import deque

def bfs_shortest_paths(n, s, adj_list):
    distances = [-1] * n
    distances[s - 1] = 0
    queue = deque([s - 1])
    while queue:
        u = queue.popleft()
        for v in range(n):
            if v != u and v + 1 not in adj_list[u + 1] and distances[v] == -1:
                distances[v] = distances[u] + 1
                queue.append(v)
    return distances

def process_test_case():
    n, m = map(int, input().split())
    adj_list = {i: set() for i in range(1, n + 1)}
    for _ in range(m):
        x, y = map(int, input().split())
        adj_list[x].add(y)
        adj_list[y].add(x)
    s = int(input())
    distances = bfs_shortest_paths(n, s, adj_list)
    result = [distances[i] for i in range(n) if i != s - 1]
    print(" ".join(map(str, result)))

def main():
    t = int(input())
    for _ in range(t):
        process_test_case()

if __name__ == "__main__":
    main()
